/* === Luka Blink Gone Theme Base === */body {
  background-image: url("/*[[bg_image]]*/");
  background-repeat: no-repeat;
  background-size: cover;
  background-position: center;
  background-attachment: fixed;
  color: white;
  font-family: "Poppins", sans-serif;
}

body::before {
  content: "";
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(0, 0, 0, 0.35);
  z-index: -1;
}

/* === Text and Accent Colors === */

/* General text color */
body, p, span, div {
  color: #f8f8ff; /* soft white */
}

/* Headings */
h1, h2, h3, h4 {
  color: #a5e1ff; /* light blue glow tone */
  text-shadow: 0 0 5px rgba(165, 225, 255, 0.5);
}

/* Links */
a {
  color: #ffb6c1; /* pastel pink */
  text-decoration: none;
  transition: color 0.3s ease;
}

a:hover {
  color: #ffd1dc; /* lighter pink */
  text-decoration: underline;
}

/* === Buttons === */
button, input[type="submit"], input[type="button"] {
  background-color: rgba(255, 182, 193, 0.8); /* pink */
  border: none;
  color: white;
  padding: 8px 16px;
  border-radius: 6px;
  font-weight: bold;
  transition: all 0.3s ease;
  cursor: pointer;
}

button:hover, input[type="submit"]:hover, input[type="button"]:hover {
  background-color: rgba(255, 209, 220, 0.9);
  transform: scale(1.05);
}

/* === Input Fields === */
input[type="text"], textarea, select {
  background-color: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.3);
  color: #f8f8ff;
  padding: 6px 10px;
  border-radius: 4px;
}

input:focus, textarea:focus {
  outline: none;
  border-color: #ffb6c1;
  box-shadow: 0 0 6px #ffb6c1;
}

/* === Optional: Card or container styling === */
div, section, article {
  background-color: rgba(0, 0, 0, 0.2);
  border-radius: 10px;
  padding: 10px;
}
